from fractions import Fraction
import math

def check_square_of_rational(x):
    """
    Checks if a rational number x is the square of another rational number.
    If it is, returns a potential rational square root (if non-negative).
    """
    if x < 0:
        return False, None

    # Check if x is zero
    if x == 0:
        return True, Fraction(0)

    # Convert to irreducible fraction p/q
    p = x.numerator
    q = x.denominator

    # Check if numerator and denominator are both perfect squares
    # This is necessary for x = (r/s)^2 where r, s are integers.
    # If x = p/q, we need p = m^2 and q = n^2 for some integers m, n.

    def is_perfect_square(n):
        if n < 0:
            return False
        if n == 0:
            return True
        # Use integer square root approximation
        root = int(math.sqrt(n))
        return root * root == n

    if is_perfect_square(p) and is_perfect_square(q):
        root_p = int(math.sqrt(p))
        root_q = int(math.sqrt(q))
        return True, Fraction(root_p, root_q)

    return False, None

def solve_for_b_squared(a):
    # Calculate b^2 = a^2 - a/(a-2)
    if a == 2:
        return None # Undefined case

    # Using Fraction for exact arithmetic
    try:
        a_frac = Fraction(a)
        term2 = a_frac / (a_frac - 2)
        b_squared = a_frac**2 - term2
        return b_squared
    except ZeroDivisionError:
        return None # Should not happen with the check above

