import math

def is_square_of_rational(x):
    """Checks if a non-negative rational number x is the square of a rational number."""
    if x < 0:
        return False, None
    if x == 0:
        return True, Fraction(0)

    p = x.numerator
    q = x.denominator

    def is_perfect_square(n):
        if n < 0: return False
        if n == 0: return True
        root = int(math.sqrt(n))
        return root * root == n

    if is_perfect_square(p) and is_perfect_square(q):
        root_p = int(math.sqrt(p))
        root_q = int(math.sqrt(q))
        return True, Fraction(root_p, root_q)

    return False, None

def calculate_b_squared(a):
    """Calculates b^2 = a^2 - a/(a-2) for rational a."""
    if a == 2:
        return None
    try:
        a_frac = Fraction(a)
        # b^2 = a^2 - a/(a-2)
        term2 = a_frac / (a_frac - 2)
        b_squared = a_frac**2 - term2
        return b_squared
    except ZeroDivisionError:
        return None

a_values = [0, 1, Fraction(-1, 1), Fraction(3, 2), Fraction(1, 2)]
